<?php
// Shared Student/Staff OTP recovery page. The caller defines $portalRecoveryRole and $portalRecoveryLabel.
require_once __DIR__ . '/admin-portal/includes/mailer.php';
$csrf = $_SESSION['portal_recovery_csrf'] ?? bin2hex(random_bytes(32)); $_SESSION['portal_recovery_csrf'] = $csrf;
$pendingKey = 'portal_recovery_' . $portalRecoveryRole;
$pending = $_SESSION[$pendingKey] ?? null; $error = ''; $notice = ''; $now = time();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  if (!hash_equals($csrf, (string) ($_POST['csrf_token'] ?? ''))) $error = 'Your session expired. Reload this page and try again.';
  else {
    $action = (string) ($_POST['action'] ?? '');
    if ($action === 'request' || $action === 'resend') {
      $email = $action === 'resend' ? (string) ($pending['email'] ?? '') : trim((string) ($_POST['email'] ?? ''));
      if ($action === 'resend' && (!$pending || (int) ($pending['resend_at'] ?? 0) > $now)) {
        $wait = max(1, (int) ($pending['resend_at'] ?? $now) - $now);
        $error = 'Please wait ' . $wait . ' seconds before requesting another code.';
        $account = null;
      } else {
      $find = $pdo->prepare('SELECT id, email FROM portal_users WHERE role = :role AND LOWER(email) = LOWER(:email) LIMIT 1'); $find->execute([':role' => $portalRecoveryRole, ':email' => $email]); $account = $find->fetch();
      }
      if (!$error && (!$account || !otp_mailer_ready())) { $error = otp_mailer_ready() ? 'No matching account was found.' : 'Email delivery is not configured yet.'; }
      else {
        $pdo->prepare("UPDATE portal_password_otp SET is_used = 1 WHERE portal_user_id = :id AND purpose = 'forgot_password' AND is_used = 0")->execute([':id' => $account['id']]);
        $code = (string) random_int(100000, 999999); $pdo->prepare("INSERT INTO portal_password_otp (portal_user_id, otp_code, purpose, expires_at) VALUES (:id, :code, 'forgot_password', DATE_ADD(NOW(), INTERVAL 10 MINUTE))")->execute([':id' => $account['id'], ':code' => $code]);
        if (send_otp_email($account['email'], $code, 'forgot_password')) { $pending = ['id' => (int) $account['id'], 'email' => $account['email'], 'expires' => $now + 600, 'resend_at' => $now + 60]; $_SESSION[$pendingKey] = $pending; $notice = $action === 'resend' ? 'A new verification code has been sent. Your previous code is no longer valid.' : 'A 6-digit verification code was sent to ' . $account['email'] . '.'; }
        else $error = 'We could not send the verification code. Please try again.';
      }
    } elseif ($action === 'verify' && $pending) {
      $code = preg_replace('/\D/', '', (string) ($_POST['otp_code'] ?? '')); $password = (string) ($_POST['new_password'] ?? ''); $confirm = (string) ($_POST['confirm_password'] ?? '');
      if (strlen($password) < 8) $error = 'Your new password must be at least 8 characters.'; elseif ($password !== $confirm) $error = 'New password and confirmation do not match.'; else {
        $otp = $pdo->prepare("SELECT id FROM portal_password_otp WHERE portal_user_id = :id AND otp_code = :code AND purpose = 'forgot_password' AND is_used = 0 AND expires_at > NOW() ORDER BY id DESC LIMIT 1 FOR UPDATE");
        try { $pdo->beginTransaction(); $otp->execute([':id' => $pending['id'], ':code' => $code]); $otpId = $otp->fetchColumn(); if (!$otpId) throw new RuntimeException('Invalid or expired code.'); $hash = password_hash($password, PASSWORD_DEFAULT); $pdo->prepare('UPDATE portal_users SET password_hash = :hash WHERE id = :id')->execute([':hash' => $hash, ':id' => $pending['id']]); $pdo->prepare("UPDATE users SET password_hash = :hash, must_change_password = 0 WHERE LOWER(email) = LOWER(:email) AND role = :role")->execute([':hash' => $hash, ':email' => $pending['email'], ':role' => $portalRecoveryRole]); $pdo->prepare('UPDATE portal_password_otp SET is_used = 1 WHERE id = :id')->execute([':id' => $otpId]); $pdo->commit(); unset($_SESSION[$pendingKey]); $_SESSION['login_notice'] = 'Password reset successfully. Sign in with your new password.'; header('Location: login.php'); exit; } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $error = $e->getMessage() === 'Invalid or expired code.' ? $e->getMessage() : 'Unable to reset your password. Please try again.'; }
      }
    }
  }
}
?>
<?php if ($pending): ?><script>window.portalOtpExpiry = <?php echo (int) ($pending['expires'] ?? 0) * 1000; ?>;</script><?php endif; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset Password | <?php echo htmlspecialchars($portalRecoveryLabel); ?></title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Newsreader:wght@600;700&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="../admin-portal/css/admin.css"></head><body class="login-body"><main class="login-shell"><section class="login-showcase"><div class="login-orb login-orb-one"></div><div class="login-orb login-orb-two"></div><div class="login-grid"></div><div class="login-showcase-brand"><span class="brand-mark login-mark"><img class="brand-logo" src="../assets/logo.svg" alt=""></span><span>College Feedback<small>Patan Nistha Campus</small></span></div><div class="login-showcase-copy"><span class="login-eyebrow">College Feedback System · <?php echo htmlspecialchars($portalRecoveryLabel); ?></span><h1>Reset securely.</h1><p>Use a verification code sent to your account email to set a new password.</p></div></section><section class="login-panel"><div class="login-content recovery-content"><div class="login-brand"><span class="brand-mark"><img class="brand-logo" src="../assets/logo.svg" alt=""></span><span><strong><?php echo htmlspecialchars($portalRecoveryLabel); ?></strong><small>College Feedback System</small></span></div><div class="login-title recovery-title"><span class="page-kicker">ACCOUNT RECOVERY</span><h1>Reset your password</h1><p><?php echo $pending ? 'Enter the verification code and choose a new password.' : 'Enter your account email to receive a 6-digit verification code.'; ?></p></div><?php if ($notice): ?><div class="otp-sent"><span class="otp-check">✓</span><span><?php echo htmlspecialchars($notice); ?></span></div><?php endif; ?><?php if ($error): ?><div class="alert alert-error"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><?php if (!$pending): ?><form method="post" class="recovery-request-form"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf); ?>"><input type="hidden" name="action" value="request"><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" required autofocus></div><button class="btn btn-primary btn-block login-submit">Send verification code</button></form><?php else: ?><form method="post" class="recovery-verify-form"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf); ?>"><input type="hidden" name="action" value="verify"><div class="field"><label for="otp_code">Verification code</label><input id="otp_code" name="otp_code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></div><div class="field password-reset-field"><label for="new_password">New password</label><span class="password-reset-input"><input id="new_password" name="new_password" type="password" minlength="8" required><button type="button" data-password-toggle="new_password" aria-label="Show password">◉</button></span></div><div class="field password-reset-field"><label for="confirm_password">Confirm new password</label><span class="password-reset-input"><input id="confirm_password" name="confirm_password" type="password" minlength="8" required><button type="button" data-password-toggle="confirm_password" aria-label="Show password">◉</button></span></div><button class="btn btn-primary btn-block">Verify &amp; reset password</button></form><form method="post" class="otp-resend"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf); ?>"><input type="hidden" name="action" value="resend"><button class="btn btn-outline">Resend code</button></form><?php endif; ?><p class="recovery-back"><a href="login.php">← Back to sign in</a></p></div></section></main><script src="../portal_password_toggle.js"></script></body></html>
